#!/usr/bin/env bash
# Evidence: the commit-scope guard refuses a BARE commit and allows a PARTIAL one — in EVERY
# repo the cortex hooks cover, not only hermes-cortex.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so the
# `generated-by` claim is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/commit-scope-guard-2026-10-22.sh
#
# captured-at: the revision the working tree sat on when this ran. The COMMITTED copy is always
# one commit AHEAD of that revision (writing this file changes the tree), so no `tip:` line is
# printed — that would be a claim about the range that the file cannot make about itself.
#
# READ-ONLY w.r.t. the fleet: the only repositories this creates are throwaway ones in the
# scratch dir, and they are deleted before the script exits. The hook never commits.
# Host paths are normalised to `~` AT THE POINT OF EMISSION, never hand-patched afterwards.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
DEPLOYED="${DEPLOYED:-$HOME/.hermes-cortex/scripts/pre-commit-score}"
HOOKS_PATH="${HOOKS_PATH:-$HOME/.hermes-cortex/hooks}"
OUT="${OUT:-$REPO/docs/evidence/commit-scope-guard-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() { sed -e "s|$HOME|~|g"; }
say()  { printf '%s\n' "$*"; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "commit-scope guard — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/commit-scope-guard-2026-10-22.sh (this file wrote itself)"
say "deployed    : ~/.hermes-cortex/scripts/pre-commit-score  (the copy that actually runs)"
say "hooks path  : ~/.hermes-cortex/hooks  (core.hooksPath — set GLOBALLY on this host, so"
say "              every repo here is 'covered by the cortex hooks')"
rule

say ""
say "0. WHAT CHANGED: the guard was scoped to hermes-cortex by ONE comparison"
say "   It is now unscoped, per the operator's instruction that the fix must work on non-hc"
say "   repos properly. The guard's scope IS the hook's own presence: this script only runs"
say "   because a repo's core.hooksPath points at the cortex hooks. A client repo or steadfaste"
say "   has the identical sweep risk — several agents, ONE index."
say ""
say "   This is NOT the Titus incident, which is why the comparison could go. That gate"
say "   (reflexion proof, governance lock, AGENTS.md audit) requires a HERMES SESSION, which a"
say "   human committing by hand does not have, so it blocked ordinary manual work in every repo"
say "   on the host. This guard requires no session — it asks only whether the commit uses the"
say "   shared index, a git fact in any repository — and its remedy is one flag, which a human"
say "   and an agent can both use. A repo that should not have this check sets its own"
say "   core.hooksPath: a config decision, not a code one."
rule

say ""
say "1. The hook's OWN self-test — the proof that travels with the blob it proves"
say "   \$ bash ops/scripts/pre-commit-score --self-test"
bash "$REPO/ops/scripts/pre-commit-score" --self-test 2>&1 | norm
say "   rc=${PIPESTATUS[0]}"
rule

say ""
say "2. LIVE refusal — the DEPLOYED hook, run for real in THIS repo with no pathspec"
say "   \$ bash ~/.hermes-cortex/scripts/pre-commit-score"
bash "$DEPLOYED" 2>&1 | norm
say "   rc=${PIPESTATUS[0]}   (1 = refused; the hook never commits, so this is safe to run)"
rule

say ""
say "3. LIVE proof in a NON-CORTEX repo — the operator's actual requirement"
say "   A throwaway repo in the scratch dir with core.hooksPath pointed at the cortex hooks:"
say "   covered by the hooks, but NOT hermes-cortex. Both directions are exercised for real."
_live="$(mktemp -d "${TMPDIR:-/tmp}/nonhc-guard.XXXXXX")"
(
  cd "$_live" || exit 1
  git init -q .
  git config user.email probe@example.com
  git config user.name probe
  git config core.hooksPath "$HOOKS_PATH"
  echo one > a.txt
  echo two > b.txt
  git add a.txt b.txt
  say "   repo under test : $_live (NOT hermes-cortex)"
  say "   core.hooksPath  : $HOOKS_PATH"
  say ""
  say "   → BARE commit (must be refused):"
  git commit -m probe 2>&1 | norm | head -6 | sed 's/^/     /'
  _bare_rc=${PIPESTATUS[0]}
  say "     rc=$_bare_rc   (1 = REFUSED — note the non-cortex wording of the message)"
  say ""
  say "   → PATHSPEC commit in the same repo (must be allowed):"
  git commit -q -m probe -- a.txt 2>&1 | norm | head -4 | sed 's/^/     /'
  say "     rc=$?   (0 = ALLOWED — the same remedy works in a non-cortex repo)"
  say "     committed     : $(git show --pretty=format: --name-only HEAD | tr '\n' ' ')"
  say "     still staged  : $(git diff --cached --name-only | tr '\n' ' ')  (not swept)"
)
rm -rf "$_live"
rule

say ""
say "4. DISCRIMINATION — an assertion that cannot fail is not evidence"
say "   (a) the SCOPE check: put the repo-root comparison BACK in a copy. The real file is"
say "       untouched; the point is that the new checks report the defect when it IS present."
_probe="$(mktemp "${TMPDIR:-/tmp}/commit-scope-scope.XXXXXX")"
cp "$REPO/ops/scripts/pre-commit-score" "$_probe"
python3 - "$_probe" <<'PY'
import sys
p = sys.argv[1]
s = open(p).read()
anchor = '  [[ "$sanctioned" == "1" ]] && return 1'
scoped = '  [[ "$repo_root" == "${HOME}/hermes-cortex" ]] || return 1\n'
if anchor not in s or scoped in s:
    print("  PREMISE FAILED — cannot construct the scoped copy"); sys.exit(2)
open(p, "w").write(s.replace(anchor, scoped + anchor, 1))
print("  scoping re-inserted into the copy")
PY
bash "$_probe" --self-test 2>&1 | norm | grep -E "^  FAIL|self-test" || true
bash "$_probe" --self-test >/dev/null 2>&1
say "   rc=$?   (1 = the copy correctly FAILS the scope checks: they are not tautologies)"
rm -f "$_probe"
say ""
say "   (b) the WIRING check: invert the call site in a copy."
_probe2="$(mktemp "${TMPDIR:-/tmp}/commit-scope-discrim.XXXXXX")"
cp "$REPO/ops/scripts/pre-commit-score" "$_probe2"
sed -i 's/^if _commit_scope_guard/if ! _commit_scope_guard/' "$_probe2"
say "   inverted lines in the copy: $(grep -cE '^if ! _commit_scope_guard' "$_probe2")"
bash "$_probe2" --self-test 2>&1 | norm | grep -E "^  FAIL|self-test" || true
bash "$_probe2" --self-test >/dev/null 2>&1
say "   rc=$?   (1 = the copy correctly FAILS the wiring checks)"
rm -f "$_probe2"
rule

say ""
say "5. Syntax + the A4 adversarial gate on every file this range changed"
for _f in ops/scripts/pre-commit-score ops/scripts/manage/bump-version.sh ops/scripts/manage/migrate-orch-bus-names.sh; do
  bash -n "$REPO/$_f" 2>&1 | norm
  _syn=$?
  python3 "$HOME/.hermes-cortex/scripts/adversarial-verify.py" --file "$REPO/$_f" --level A4 --gate >/dev/null 2>&1
  _adv=$?
  say "   $_f  syntax_rc=$_syn  A4_rc=$_adv"
done
rule

say ""
say "6. What the guard keys on, MEASURED rather than assumed"
say "   (section 1 prints the two GIT_INDEX_FILE values git actually passes the hook: the repo's"
say "    own index for a bare commit, a throwaway next-index-*.lock for a partial one — and the"
say "    unnamed file is still staged afterwards, so a partial commit cannot have swept it.)"
rule

say ""
say "7. REPORTED, NOT EDITED — foreign call sites the widened guard will now refuse"
say "   The cross-repo handoff rule: repos the fleet does not own are reported, not edited."
say "   ~/.hermes/hermes-agent carries bare-commit call sites. Live check:"
_grep="$(grep -rn "git add -A && git commit" "$HOME/.hermes/hermes-agent" \
          --include="*.sh" --include="*.py" --include="*.md" 2>/dev/null | norm | head -8)"
if [[ -n "$_grep" ]]; then printf '%s\n' "$_grep" | sed 's/^/     /'; else say "     (none found)"; fi
say ""
say "   Those commits will now be REFUSED in that repo, because the global core.hooksPath puts"
say "   the cortex hook in front of every commit made on this host. The operator owns that fix."
rule

say ""
say "8. The range this evidence belongs to"
say "   UNCOMMITTED at capture time — the committed copy lands one commit after this run, so"
say "   naming a commit here would be a claim the file cannot make about itself."
say "   HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- ops/scripts/pre-commit-score ops/scripts/manage/bump-version.sh ops/scripts/manage/migrate-orch-bus-names.sh docs/evidence/commit-scope-guard-2026-10-22.sh docs/evidence/commit-scope-guard-2026-10-22.txt | norm | sed 's/^/     /')
rule
say ""
say "end of evidence"
